style.css:
/* Pinterest Dark Theme for Stylish */

/* General background */
body, html {
    background-color: #000 !important;
    color: #fff !important;
}

/* Main feed background */
div[data-test-id="homefeed"],
div[data-test-id="pinGrid"],
div[data-test-id="boardFeed"],
div[data-test-id="searchFeed"],
div[data-test-id="pin"] {
    background-color: #000 !important;
}

/* Pin cards */
div[data-test-id="pin"],
div[data-test-id="pinWrapper"] {
    background-color: #111 !important;
    border-radius: 12px !important;
}

/* Text */
span, p, h1, h2, h3, h4, h5, h6, a {
    color: #fff !important;
}

/* Navigation bar */
header, nav, div[data-test-id="appHeader"] {
    background-color: #111 !important;
    color: #fff !important;
    border-bottom: 1px solid #222 !important;
}

/* Search bar */
input[type="search"],
input[placeholder*="Search"] {
    background-color: #222 !important;
    color: #fff !important;
    border-radius: 20px !important;
    border: 1px solid #444 !important;
}

/* Buttons */
button {
    background-color: #222 !important;
    color: #fff !important;
    border: none !important;
}

button:hover {
    background-color: #333 !important;
}

/* Remove white borders/highlights */
* {
    border-color: #222 !important;
}

/* Logo inversion */
svg, img {
    filter: brightness(0) invert(1) !important;
}
